<script setup lang="ts">
import { computed, onMounted, ref } from "vue"; import { useRoute } from "vue-router"; import { http } from "@/utils/http";
type Row = Record<string, unknown>; const route = useRoute(); const query = ref(""); const tab = ref("catalog"); const rows = ref<Row[]>([]); const loading = ref(false); const error = ref("");
const kind = computed(() => String(route.path.split("/").pop())); const title = computed(() => ({ music: "音乐库", photos: "照片管理", games: "游戏档案" }[kind.value] || "媒体目录"));
async function load() { loading.value = true; try { const endpoint = kind.value === "music" ? "/music/playlists" : kind.value === "photos" ? "/photos/timeline" : "/games"; const result = await http.get<unknown, unknown>(endpoint); rows.value = Array.isArray(result) ? result as Row[] : []; } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "媒体目录加载失败"; } finally { loading.value = false; } }
onMounted(load);
</script>
<template><main class="p-4 md:p-6"><div class="flex justify-between items-start mb-6"><div><h1 class="text-2xl font-semibold">{{ title }}</h1><p class="mt-1 text-[var(--el-text-color-secondary)]">资源、附件和技术元数据分层管理，敏感内容遵循授权边界。</p></div><el-button :loading="loading" @click="load">刷新</el-button></div><el-alert v-if="error" :title="error" type="warning" show-icon :closable="false" class="mb-4"/><el-tabs v-model="tab"><el-tab-pane label="目录" name="catalog"/><el-tab-pane label="元数据" name="metadata"/><el-tab-pane label="播放 / 时间线" name="activity"/></el-tabs><el-card shadow="never"><template #header><div class="flex justify-between"><span>{{ title }}目录</span><el-input v-model="query" clearable placeholder="搜索标题或资源 ID" class="w-64"/></div></template><el-skeleton v-if="loading" :rows="5" animated/><el-empty v-else-if="!rows.length" description="暂无可展示条目；其他媒体目录接口尚未接入"/><el-table v-else :data="rows" stripe><el-table-column prop="id" label="ID" min-width="240"/><el-table-column prop="name" label="名称" min-width="200"/><el-table-column prop="status" label="状态" width="140"/><el-table-column prop="createdAt" label="创建时间" min-width="180"/></el-table><el-alert title="附件物理存储请在“附件与存储”模块管理。" type="info" show-icon :closable="false" class="mt-4"/></el-card></main></template>
